def findTheDifference(s: str, t: str) -> str:
    # Initialize result variable to 0
    result = 0

    # XOR all characters from s
    for char in s:
        result ^= ord(char)

    # XOR all characters from t
    for char in t:
        result ^= ord(char)

    # The result now represents the ASCII of the extra character
    return chr(result)
